const rows=$input.all().map(i=>i.json||{}); const candidates=[]; for(const r of rows){ if(r.task_id){ if(r.priority==='P0'||r.human_action_required===true||r.cash_stage==='paid_blocked'||r.cash_stage==='payment_due_now'){ const rank=r.human_action_required===true?0:(r.cash_stage==='paid_blocked'?0:(r.cash_stage==='payment_due_now'?1:2)); candidates.push({key:'task:'+r.task_id,rank,value:Number(r.revenue_value||0),client:r.client_name||'بدون اسم',text:r.objective||r.next_action||'مهمة',human:r.human_action_required===true,type:'task'}); } continue; } if(!r.deal_id) continue; const exec=String(r.execution_status||'').toLowerCase(); const pay=String(r.payment_status||'').toLowerCase(); const inv=String(r.invoice_status||'').toLowerCase(); const contract=String(r.contract_status||'').toLowerCase(); const quote=String(r.quote_status||'').toLowerCase(); const value=Number(r.deal_value||r.quoted_amount||r.invoiced_amount||0); let issue=null; if(r.human_action_required===true){issue={rank:0,text:r.next_action||'خطوة بشرية مطلوبة منك',human:true};} else if(Number(r.paid_amount||0)>0 && !['completed','delivered'].includes(exec) && String(r.stage||'').toLowerCase()!=='delivered'){issue={rank:0,text:`عميل دفع ${Number(r.paid_amount||0).toLocaleString('en-US')} ريال والتنفيذ غير مكتمل`,human:false};} else if(contract==='signed' && !['issued','sent','paid'].includes(inv)){issue={rank:1,text:'العقد موقع ولم تصدر/ترسل الفاتورة',human:false};} else if(['issued','sent'].includes(inv) && pay!=='paid'){issue={rank:1,text:`فاتورة صادرة والتحصيل ما زال ${pay||'معلق'}`,human:false};} else if(quote==='accepted' && contract!=='signed'){issue={rank:2,text:'العرض مقبول والعقد لم يكتمل بعد',human:false};} if(issue)candidates.push({key:'deal:'+r.deal_id,rank:issue.rank,value,client:r.client_name||r.deal_id,text:issue.text,human:issue.human,type:'deal'}); } const uniq=new Map(); for(const c of candidates){const k=(c.client+'|'+c.text).toLowerCase(); if(!uniq.has(k)||uniq.get(k).rank>c.rank) uniq.set(k,c);} const top=[...uniq.values()].sort((a,b)=>a.rank-b.rank||b.value-a.value).slice(0,5); if(!top.length)return [{json:{notify:false,message:''}}]; const lines=top.map((c,i)=>`${i+1}) ${c.client} — ${c.text}${c.value?` — ${c.value.toLocaleString('en-US')} ريال`:''}${c.human?' — 👤 عليك أنت':''}`); const paid=top.filter(c=>c.rank===0&&!c.human).length; const human=top.filter(c=>c.human).length; const msg=`🧠 مُعين — Focus الآن
${paid?`🔴 ${paid} حالة كاش/تنفيذ عاجلة
`:''}${human?`👤 ${human} خطوة عليك أنت
`:''}
